package com.ebdf.controller;
import com.ebdf.dao.PortalDAO;import com.google.gson.*;import javax.servlet.annotation.WebServlet;import javax.servlet.http.*;import java.io.*;import java.util.*;
@WebServlet("/api/profile") public class AccountProfileServlet extends HttpServlet {
 private final PortalDAO dao=new PortalDAO();private final Gson gson=new Gson();
 private Integer user(HttpServletRequest q,HttpServletResponse p)throws IOException{HttpSession s=q.getSession(false);if(s==null||s.getAttribute("userId")==null){p.setStatus(401);p.getWriter().write("{\"message\":\"Please login first\"}");return null;}return ((Number)s.getAttribute("userId")).intValue();}
 protected void doGet(HttpServletRequest q,HttpServletResponse p)throws IOException{p.setContentType("application/json");p.setCharacterEncoding("UTF-8");Integer id=user(q,p);if(id==null)return;try{p.getWriter().write(gson.toJson(dao.accountProfile(id)));}catch(Exception e){p.setStatus(500);p.getWriter().write("{\"message\":\"Unable to load profile\"}");}}
 protected void doPut(HttpServletRequest q,HttpServletResponse p)throws IOException{p.setContentType("application/json");p.setCharacterEncoding("UTF-8");Integer id=user(q,p);if(id==null)return;try{JsonObject b=gson.fromJson(q.getReader(),JsonObject.class);String name=b.get("fullName").getAsString().trim(),phone=b.get("phone").getAsString().trim();if(name.length()<2||name.length()>120||!phone.matches("[0-9]{10,15}")){p.setStatus(400);p.getWriter().write("{\"message\":\"Enter a valid name and 10-15 digit phone number\"}");return;}if(!dao.updateAccountProfile(id,name,phone)){p.setStatus(404);p.getWriter().write("{\"message\":\"Profile not found\"}");return;}q.getSession(false).setAttribute("fullName",name);p.getWriter().write("{\"message\":\"Profile updated successfully\"}");}catch(Exception e){p.setStatus(400);p.getWriter().write("{\"message\":\"Unable to update profile\"}");}}
}
